#!/usr/bin/env node
// Independent naive enumeration of actual source-pair and third-clause RES.
// The original source is regenerated by Python's seeded sampler, SHA256 checked,
// and every inference is checked by independent JS logic. Not historical R_mix341.
import assert from 'node:assert/strict';
import {execFileSync} from 'node:child_process';
import crypto from 'node:crypto';
const fixtureCode='import json; from lspv3_459_width4_5 import source; print(json.dumps(source(64,11)))';
const cnf=JSON.parse(execFileSync('python3',['-c',fixtureCode],{cwd:process.cwd(),encoding:'utf8'}));
const fix={n:64,seed:11,sha256:'f9706c9cf9d82e08ecca3d091861aaece60922411632266396d85843265698d7',
  actual:{z3:294,z4:8628,t5:375418,samples4:[],samples5:[]}};
const sha=xs=>crypto.createHash('sha256').update(xs.map(x=>x.join(' ')+' 0').join('\n')+'\n').digest('hex');
assert.equal(sha(cnf),fix.sha256);
const literalSignature=c=>new Set(c.map(x=>Math.abs(x)));
function resolveExact(a,b,pivot){
  if (!(a.includes(pivot)&&b.includes(-pivot)))return null;
  const r=[...new Set([...a.filter(x=>Math.abs(x)!==Math.abs(pivot)),
      ...b.filter(x=>Math.abs(x)!==Math.abs(pivot))])];
  if (r.some(x=>r.includes(-x)))return null;
  return r.sort((a,b)=>Math.abs(a)-Math.abs(b)||a-b);
}
function allPivots(a,b){
  const found=[];
  for(const x of a){
    if(!b.includes(-x))continue;
    const c=resolveExact(a,b,x);
    if(c)found.push([x,c]);
  }
  return found;
}
function shareCount(a,b){
  const s=literalSignature(a);
  return [...literalSignature(b)].filter(x=>s.has(x)).length;
}
let z4=0,t5=0,z3=0,witnesses=0;
for(let a=0;a<cnf.length;a++)for(let b=a+1;b<cnf.length;b++){
  const A=cnf[a],B=cnf[b];
  if(shareCount(A,B)===2 && allPivots(A,B).some(([p,r])=>r.length===3))z3++;
  if(shareCount(A,B)!==1)continue;
  for(const [p,R] of allPivots(A,B)){
    if(R.length!==4)continue;
    z4++;
    for(let c=0;c<cnf.length;c++){
      if(c===a||c===b)continue;
      const C=cnf[c];
      if(shareCount(R,C)!==1)continue;
      for(const [q,S] of allPivots(R,C)){
        if(S.length===5)t5++;
        if(witnesses<5){assert.equal(shareCount(R,C),1);witnesses++;}
      }
    }
  }
}
assert.equal(z4,fix.actual.z4);
assert.equal(z3,fix.actual.z3);
assert.equal(t5,fix.actual.t5);
let rejects=0;
for(const bad of [
 ()=>assert.equal(sha([...cnf.slice(0,-1),cnf[cnf.length-1].map(x=>-x)]),fix.sha256),
 ()=>assert.deepEqual(resolveExact(cnf[0],cnf[0],999),[1,2,3,4]),
 ()=>assert.equal(z4+1,fix.actual.z4),
 ()=>assert.equal(t5+1,fix.actual.t5),
 ()=>assert.equal(cnf.length+1,8*fix.n)
]){
 try{bad();throw Error('hostile mutation accepted')}
 catch(e){if(e.message==='hostile mutation accepted')throw e;rejects++;}
}
console.log(JSON.stringify({status:'PASS independent JS naive all-pair/third enumeration',
 n:fix.n,m:cnf.length,z3,z4,t5,witnesses,hostile_rejections:rejects,
 source_sha256:sha(cnf)},null,2));
